select is((select status from public.customer_success_tasks where tenant_id='e3200000-0000-4000-8000-000000000001' and kind='WINBACK'),'DISMISSED','reactivated subscription retires win-back task');
select is((select count(*) from public.subscription_payments where tenant_id='e3200000-0000-4000-8000-000000000001'),1::bigint,'reviews preserve immutable payment periods');
select is((select count(*) from public.messages where tenant_id='e3200000-0000-4000-8000-000000000001' and direction='outbound'),0::bigint,'renewal churn and win-back still send nothing');

-- Failed work is bounded, and a later source still uses current evidence.
create function pg_temp.p13_fail_fixture() returns trigger language plpgsql as $$begin raise exception 'synthetic worker fault';end;$$;
create trigger p13_fail_fixture before insert on public.customer_success_tasks for each row execute function pg_temp.p13_fail_fixture();
select private.success_enqueue('e3200000-0000-4000-8000-000000000001','e3300000-0000-4000-8000-000000000003','bounded-failure');
update public.scheduled_jobs set max_attempts=1 where idempotency_key like '%bounded-failure';
select public.process_customer_success_jobs('e3200000-0000-4000-8000-000000000001',100);
select is((select status from public.scheduled_jobs where tenant_id='e3200000-0000-4000-8000-000000000001' and idempotency_key like '%bounded-failure'),'dead_letter','unrecoverable fixture is bounded by max attempts');
select is((select last_error_code from public.scheduled_jobs where tenant_id='e3200000-0000-4000-8000-000000000001' and idempotency_key like '%bounded-failure'),'P0001','worker stores code only, not private error text');
drop trigger p13_fail_fixture on public.customer_success_tasks;
set local role authenticated;select set_config('request.jwt.claim.sub','e3100000-0000-4000-8000-000000000001',true);
select is(public.admin_success_list('e3200000-0000-4000-8000-000000000001')->'queue_health'->>'failed','1','failed source review remains visible to operators');
select ok(public.admin_success_retry_review('e3200000-0000-4000-8000-000000000001',(select id from public.scheduled_jobs where tenant_id='e3200000-0000-4000-8000-000000000001' and idempotency_key like '%bounded-failure'),1),'manager can retry a failed read-only review');
select throws_ok($$select public.admin_success_retry_review('e3200000-0000-4000-8000-000000000001',(select id from public.scheduled_jobs where tenant_id='e3200000-0000-4000-8000-000000000001' and idempotency_key like '%bounded-failure'),1)$$,'PT409','review job changed','duplicate retry cannot erase attempts or replay a completed claim');
reset role;
select is(public.process_customer_success_due()->>'mode','PREVIEW_ONLY','scheduled worker never gains send authority');
select is((select status from public.scheduled_jobs where tenant_id='e3200000-0000-4000-8000-000000000001' and idempotency_key like '%bounded-failure'),'completed','retried source review recovers from current evidence');
select is((select count(*) from public.audit_logs where tenant_id='e3200000-0000-4000-8000-000000000001' and action='success.review_job_failed'),1::bigint,'unsuccessful worker evidence is retained');
select is((select count(*) from public.audit_logs where tenant_id='e3200000-0000-4000-8000-000000000001' and action='success.review_job_retried'),1::bigint,'manual retry is audited');

select public.configure_phase13_sandbox('e3200000-0000-4000-8000-000000000001',false);
select throws_ok($$select public.process_customer_success_jobs('e3200000-0000-4000-8000-000000000001')$$,'42501','isolated sandbox required','disabled engine cannot process');
set local role anon;
select throws_ok($$select public.admin_success_list('e3200000-0000-4000-8000-000000000001')$$,'42501',null,'anonymous queue access denied');
reset role;
select * from finish();
rollback;
